over{background:rgba(255,255,255,0.15)}.empty-state[data-v-7efac90e]{text-align:center;color:#888;padding:10px}.wb-accordion-item[data-v-7efac90e]{border:1px solid var(--SmartThemeBorderColor,rgba(255,255,255,0.1));border-radius:6px;margin-bottom:8px;background:rgba(0,0,0,0.2);overflow:hidden}.wb-accordion-header[data-v-7efac90e]{display:flex;flex-direction:column;align-items:stretch;gap:8px;padding:10px 12px;cursor:pointer;background:rgba(0,0,0,0.1);transition:background-color 0.2s}.wb-accordion-header[data-v-7efac90e]:hover{background:rgba(255,255,255,0.05)}.wb-accordion-title[data-v-7efac90e]{display:flex;align-items:center;gap:8px;font-weight:bold;width:100%}.wb-name-text[data-v-7efac90e]{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1}.wb-type-badge[data-v-7efac90e]{font-size:0.75em;padding:2px 6px;border-radius:4px;background:rgba(128,128,128,0.3);flex-shrink:0}.wb-type-badge.char[data-v-7efac90e]{background:rgba(0,123,255,0.4);color:#cce5ff}.wb-type-badge.global[data-v-7efac90e]{background:rgba(40,167,69,0.4);color:#d4edda}.wb-accordion-actions[data-v-7efac90e]{display:flex;align-items:center;justify-content:flex-end;gap:12px;padding-top:4px;border-top:1px dashed rgba(255,255,255,0.1)}.accordion-arrow[data-v-7efac90e]{font-size:0.8em;opacity:0.6;margin-left:4px}.wb-entries-wrapper[data-v-7efac90e]{border-top:1px solid rgba(255,255,255,0.05);background:rgba(0,0,0,0.1);padding-top:10px}.wb-entries-container[data-v-7efac90e]{padding:0 10px 10px 10px}.wb-item[data-v-7efac90e]{display:flex;flex-direction:column;align-items:stretch;padding:10px 0;border-bottom:1px solid rgba(255,255,255,0.1);transition:opacity 0.3s;gap:8px}.wb-info[data-v-7efac90e]{display:flex;align-items:flex-start;gap:10px;width:100%}.batch-checkbox-container[data-v-7efac90e]{display:flex;align-items:center;height:24px;cursor:pointer;margin-top:2px}.wb-info-text[data-v-7efac90e]{display:flex;flex-direction:column;gap:4px;min-width:0;flex:1}.wb-name[data-v-7efac90e]{font-weight:b