ht: 0;\\n  bottom: 0;\\n  background-color: #ccc;\\n  transition: 0.4s;\\n}\\n.slider:before {\\n  position: absolute;\\n  content: '';\\n  height: 16px;\\n  width: 16px;\\n  left: 2px;\\n  bottom: 2px;\\n  background-color: white;\\n  transition: 0.4s;\\n}\\ninput:checked + .slider {\\n  background-color: #007bff;\\n}\\ninput:checked + .slider:before {\\n  transform: translateX(20px);\\n}\\n.slider.round {\\n  border-radius: 20px;\\n}\\n.slider.round:before {\\n  border-radius: 50%;\\n}\\n.btn-primary, .btn-danger, .btn-success, .btn-warning {\\n  flex: 1;\\n  padding: 10px;\\n  border: none;\\n  border-radius: 4px;\\n  cursor: pointer;\\n  font-weight: bold;\\n  color: white;\\n}\\n.btn-primary {\\n  background: #007bff;\\n}\\n.btn-primary:hover {\\n  background: #0056b3;\\n}\\n.btn-danger {\\n  background: #dc3545;\\n}\\n.btn-danger:hover {\\n  background: #a71d2a;\\n}\\n.btn-success {\\n  background: #28a745;\\n}\\n.btn-success:hover {\\n  background: #218838;\\n}\\n.btn-warning {\\n  background: #ff9800;\\n}\\n.btn-warning:hover {\\n  background: #e68a00;\\n}\\n.wb-actions {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 15px;\\n  margin-bottom: 20px;\\n}\\n.ark-btn {\\n  position: relative;\\n  height: 48px;\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  cursor: pointer;\\n  border: 1px solid var(--ui-border-primary);\\n  background: var(--ui-bg);\\n  transition: all 0.2s ease;\\n  overflow: hidden;\\n}\\n.ark-btn .btn-content {\\n  display: flex;\\n  align-items: center;\\n  gap: 10px;\\n  z-index: 2;\\n  transition: all 0.2s;\\n}\\n.ark-btn .btn-text {\\n  font-weight: bold;\\n  letter-spacing: 1px;\\n  text-transform: uppercase;\\n  font-size: 0.9em;\\n}\\n.ark-btn.warning {\\n  border-color: #ff9800;\\n  color: #ff9800;\\n}\\n.ark-btn.warning:hover {\\n  background: #ff9800;\\n  color: #fff;\\n}\\n.ark-btn.danger {\\n  border-color: #f44336;\\n  color: #f44336;\\n}\\n.ark-btn.danger:hover {\\n  background: #f44336;\\n