tch input {\\n  opacity: 0;\\n  width: 0;\\n  height: 0;\\n}\\n.slider {\\n  position: absolute;\\n  cursor: pointer;\\n  top: 0;\\n  left: 0;\\n  right: 0;\\n  bottom: 0;\\n  background-color: #ccc;\\n  transition: 0.4s;\\n}\\n.slider:before {\\n  position: absolute;\\n  content: '';\\n  height: 16px;\\n  width: 16px;\\n  left: 2px;\\n  bottom: 2px;\\n  background-color: white;\\n  transition: 0.4s;\\n}\\ninput:checked + .slider {\\n  background-color: #007bff;\\n}\\ninput:checked + .slider:before {\\n  transform: translateX(20px);\\n}\\n.slider.round {\\n  border-radius: 20px;\\n}\\n.slider.round:before {\\n  border-radius: 50%;\\n}\\n.btn-primary, .btn-danger, .btn-success, .btn-warning {\\n  flex: 1;\\n  padding: 10px;\\n  border: none;\\n  border-radius: 4px;\\n  cursor: pointer;\\n  font-weight: bold;\\n  color: white;\\n}\\n.btn-primary {\\n  background: #007bff;\\n}\\n.btn-primary:hover {\\n  background: #0056b3;\\n}\\n.btn-danger {\\n  background: #dc3545;\\n}\\n.btn-danger:hover {\\n  background: #a71d2a;\\n}\\n.btn-success {\\n  background: #28a745;\\n}\\n.btn-success:hover {\\n  background: #218838;\\n}\\n.btn-warning {\\n  background: #ff9800;\\n}\\n.btn-warning:hover {\\n  background: #e68a00;\\n}\\n.wb-actions {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 15px;\\n  margin-bottom: 20px;\\n}\\n.ark-btn {\\n  position: relative;\\n  height: 48px;\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  cursor: pointer;\\n  border: 1px solid var(--ui-border-primary);\\n  background: var(--ui-bg);\\n  transition: all 0.2s ease;\\n  overflow: hidden;\\n}\\n.ark-btn .btn-content {\\n  display: flex;\\n  align-items: center;\\n  gap: 10px;\\n  z-index: 2;\\n  transition: all 0.2s;\\n}\\n.ark-btn .btn-text {\\n  font-weight: bold;\\n  letter-spacing: 1px;\\n  text-transform: uppercase;\\n  font-size: 0.9em;\\n}\\n.ark-btn.warning {\\n  border-color: #ff9800;\\n  color: #ff9800;\\n}\\n.ark-btn.warning:hover {\\n  background: #ff9800;\\n  color: #fff;\\n}\\n.ark-btn.danger {\\n  border-color: #f44336;\\n  color: #f44336;\\n}\\n.ark-btn.danger:hover {\\n  background: #f44336;\\n  color: #fff;\\n}\\n.ark-btn::after {\\n  content: '';\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 0;\\n  height: 0;\\n  border-style: solid;\\n  border-width: 0 10px 10px 0;\\n  border-color: transparent currentColor transparent transparent;\\n  opacity: 0.5;\\n}\\n.ark-btn:active {\\n  transform: scale(0.98);\\n}\\n\",\"\\n@import '../styles/theme.scss';\\n\\n/* Settings Panel */\\n.settings-panel {\\n  position: absolute;\\n  top: 0;\\n  right: calc(var(--panel-width) * -1);\\n  width: var(--panel-width);\\n  height: 100%;\\n  background-color: var(--ui-bg);\\n  backdrop-filter: blur(12px);\\n  border-left: 1px solid var(--ui-border-primary);\\n  z-index: 1000;\\n  padding: 20px;\\n  transition: right 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);\\n  box-sizing: border-box; /* Prevent padding from adding to width */\\n}\\n\\n.settings-panel.is-open {\\n  right: 0;\\n}\\n\\n/* Overlay Backdrop */\\n.settings-overlay {\\n  position: absolute;\\n  top: 0;\\n  left: 0;\\n  width: 100%;\\n  height: 100%;\\n  background-color: rgba(0, 0, 0, 0.5);\\n  z-index: 999; /* Below panel (1000), above content */\\n  backdrop-filter: blur(2px);\\n}\\n\\n.settings-divider {\\n  height: 1px;\\n  background-color: var(--ui-border-primary);\\n  margin: 20px 0;\\n}\\n\\n.theme-buttons-container {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 10px;\\n  margin-top: 15px;\\n}\\n\\n.theme-button {\\n  width: 100%;\\n  height: 50px;\\n  border-radius: 4px;\\n  cursor: pointer;\\n  border: 2px solid var(--ui-border-primary);\\n  position: relative;\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n}\\n\\n.theme-button.light {\\n  background-color: #fafafa;\\n  color: #1a1a1a;\\n}\\n.theme-button.dark {\\n  background-color: #2a2a2a;\\n  color: #e0e0e0;\\n}\\n.theme-button.transparent {\\n  background: linear-gradient(135deg, rgba(200, 200, 200, 0.1), rgba(100, 100, 100, 0.1));\\n  color: var(--ui-text-main);\\n  backdrop-filter: blur(4px);\\n}\\n.theme-button.active {\\n  border-color: var(--ui-accent);\\n}\\n\\n.theme-button {\\n  padding: 5px;\\n}\\n\\n.theme-button span {\\n  position: absolute;\\n  bottom: 5px;\\n  right: 10px;\\n  font-size: 0.8em;\\n  font-weight: bold;\\n}\\n\\n.setting-item {\\n  display: flex;\\n  justify-content: space-between;\\n  align-items: center;\\n  margin-bottom: 20px;\\n}\\n\\nh3 {\\n  color: var(--ui-text-main);\\n  font-weight: 500;\\n  font-size: 1.2em;\\n}\\n\\n/* --- Arknights Style UI --- */\\n\\n/* Status Display */\\n.wb-status-display {\\n  padding: 15px;\\n  margin-bottom: 20px;\\n  background: rgba(0, 0, 0, 0.05);\\n  border-left: 4px solid #999;\\n  position: relative;\\n  overflow: hidden;\\n}\\n\\n.wb-status-display .status-label {\\n  font-size: 0.7em;\\n  letter-spacing: 2px;\\n  color: var(--ui-text-secondary);\\n  margin-bottom: 5px;\\n}\\n\\n.wb-status-display .status-value {\\n  font-size: 1.2em;\\n  font-weight: bold;\\n  letter-spacing: 1px;\\n}\\n\\n.wb-status-display .status-diff {\\n  margin-top: 8px;\\n  font-size: 0.8em;\\n  opacity: 0.8;\\n  line-height: 1.4;\\n}\\n\\n.wb-status-display .status-decor {\\n  position: absolute;\\n  top: 0;\\n  right: 0;\\n  width: 20px;\\n  height: 20px;\\n  background: linear-gradient(45deg, transparent 50%, rgba(255, 255, 255, 0.1) 50%);\\n}\\n\\n.status-green {\\n  border-left-color: #4caf50;\\n  color: #4caf50;\\n  background: rgba(76, 175, 80, 0.05);\\n}\\n.status-blue {\\n  border-left-color: #2196f3;\\n  color: #2196f3;\\n  background: rgba(33, 150, 243, 0.05);\\n}\\n.status-orange {\\n  border-left-color: #ff9800;\\n  color: #ff9800;\\n  background: rgba(255, 152, 0, 0.05);\\n}\\n\\n.warning-box {\\n  background-color: rgba(255, 165, 0, 0.1);\\n  border-left: 3px solid var(--warning-accent);\\n  margin-bottom: 20px;\\n  padding: 15px;\\n  font-size: 0.9em;