ncludes('明日方舟') : false;\r\n  } catch (e) {\r\n    console.error('[ARK_STATUSBAR] identity check failed:', e);\r\n    return false;\r\n  }\r\n}\r\n","import { checkIsArknights } from '../utils/identity';\r\n\r\nconst MOUNT_INTERVAL_MS = 500;\r\nexport const STARTUP_CONTAINER_CLASS = 'ark-startup-mount-point';\r\nexport const RETURN_BTN_CONTAINER_CLASS = 'ark-return-btn-mount-point';\r\n\r\nlet mountLoopTimer: number | null = null;\r\nlet lastIsArknights: boolean | null = null;\r\n\r\nexport function updateIdentityAndBroadcast() {\r\n  const isArknights = checkIsArknights();\r\n\r\n  if (lastIsArknights !== isArknights) {\r\n    lastIsArknights = isArknights;\r\n    document.dispatchEvent(new CustomEvent('ark:identity-updated', { detail: { isArknights } }));\r\n  }\r\n}\r\n\r\nexport function startChatMonitor() {\r\n  if (mountLoopTimer !== null) {\r\n    window.clearInterval(mountLoopTimer);\r\n  }\r\n\r\n  // 立即触发一次\r\n  updateIdentityAndBroadcast();\r\n  \r\n  // 监听 CHAT_CHANGED 以便切卡瞬间马上识别身份\r\n  if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined') {\r\n    eventOn(tavern_events.CHAT_CHANGED, updateIdentityAndBroadcast);\r\n  }\r\n\r\n  mountLoopTimer = window.setInterval(() => {\r\n    try {\r\n      if (typeof SillyTavern === 'undefined' || !SillyTavern.chat) {\r\n        return; // 环境未就绪\r\n      }\r\n\r\n      // 1. 定位第 0 楼消息\r\n      const $message0 = $('#chat > .mes[mesid=\"0\"]');\r\n      if ($message0.length === 0) return;\r\n\r\n      const isUser = $message0.attr('is_user') === 'true';\r\n      if (isUser) return; // 仅在 AI 消息楼层挂载开局UI或返回按钮\r\n\r\n      const $mesText = $message0.find('.mes_text');\r\n      if ($mesText.length === 0) return;\r\n      \r\n      const containerEl = $mesText[0] as HTMLElement;\r\n\r\n      // 2. 强制同步鉴权\r\n      const isArknights = checkIsArknights();\r\n      updateIdentityAndBroadcast();\r\n\r\n      if (!isArknights) {\r\n        document.dispatchEvent(new CustomEvent('ark:chat-unmount-all', { detail: { containerEl } }));\r\n        return;\r\n      }\r\n\r\n      // 3. 检查当前处于哪个 Swipe ID\r\n      const firstMessage = SillyTavern.chat[0];\r\n      const swipeId = firstMessage.swipe_id || 0;\r\n\r\n      // 4. 判断逻辑\r\n      if (swipeId === 0) {\r\n        document.dispatchEvent(new CustomEvent('ark:chat-mount-startup', { detail: { containerEl } }));\r\n      } else {\r\n        document.dispatchEvent(new CustomEvent('ark:chat-mount-return', { detail: { containerEl } }));\r\n      }\r\n    } catch (error) {\r\n      console.error('[ARK_STATUSBAR] Mounting loop error:', error);\r\n    }\r\n  }, MOUNT_INTERVAL_MS);\r\n}\r\n\r\nexport function stopChatMonitor() {\r\n  if (mountLoopTimer !== null) {\r\n    window.clearInterval(mountLoopTimer);\r\n    mountLoopTimer = null;\r\n  }\r\n}\r\n","const LOCK_KEY = '__ARK_STATUSBAR_ACTIVE_LOCK__';\r\n\r\n/**\r\n * 尝试获取全局单例锁\r\n * @returns {boolean} 是否成功获取锁。如果返回 false，说明已经有实例在运行，当前脚本应该立即终止。\r\n */\r\nexport function acquireInstanceLock(): boolean {\r\n  // Tavern Helper 脚本运行在 iframe 中，真正的宿主是 window.parent\r\n  const ST_WINDOW = window.parent || window;\r\n  \r\n  if ((ST_WINDOW as any)[LOCK_KEY]) {\r\n    console.error('[ARK_STATUSBAR] Critical Error: Multiple instances detected. Aborting bootstrap.');\r\n    // 尝试在宿主页面抛出红色警告\r\n    if (typeof (ST_WINDOW as any).toastr !== 'undefined') {\r\n      (ST_WINDOW as any).toastr.error(\r\n        '检测到 Ark StatusBar 多开，为防止数据与 UI 损坏，次生实例已强制自我终止！请检查您的插件列表。',\r\n        '严重警告',\r\n        { timeOut: 5000 }\r\n      );\r\n    } else if (typeof toastr !== 'undefined') {\r\n      toastr.error(\r\n        '检测到 Ark StatusBar 多开，为防止数据与 UI 损坏，次生实例已强制自我终止！请检查您的插件列表。',\r\n        '严重警告',\r\n        { timeOut: 5000 }\r\n      );\r\n    }\r\n    return false;\r\n  }\r\n  \r\n  // 占用锁\r\n  (ST_WINDOW as any)[LOCK_KEY] = true;\r\n  return true;\r\n}\r\n\r\n/**\r\n * 释放全局单例锁\r\n */\r\nexport function releaseInstanceLock() {\r\n  const ST_WINDOW = window.parent || window;\r\n  delete (ST_WINDOW as any)[LOCK_KEY];\r\n}\r\n","\n      import API from \"!../../../node_modules/.pnpm/style-loader@4.0.0_webpack@5.106.2/node_modules/style-loader/dist/runtime/injectStylesIntoStyleTag.js\";\n      import domAPI from \"!../../../node_modules/.pnpm/style-loader@4.0.0_webpack@5.106.2/node_modules/style-loader/dist/runtime/styleDomAPI.js\";\n      import insertFn from \"!../../../node_modules/.pnpm/style-loader@4.0.0_webpack@5.106.2/node_modules/style-loader/dist/runtime/insertBySelector.js\";\n      import setAttributes from \"!../../../node_modules/.pnpm/style-loader@4.0.0_webpack@5.106.2/node_modules/style-loader/dist/runtime/setAttributesWithoutAttributes.js\";\n      import insertStyleElement from \"!../../../node_modules/.pnpm/style-loader@4.0.0_webpack@5.106.2/node_modules/style-loader/dist/runtime/insertStyleElement.js\";\n      import styleTagTransformFn from \"!../../../node_modules/.pnpm/style-loader@4.0.0_webpack@5.106.2/node_modules/style-loader/dist/runtime/styleTagTransform.js\";\n      import content, * as namedExport from \"!!../../../node_modules/.pnpm/css-loader@7.1.4_webpack@5.106.2/node_modules/css-loader/dist/cjs.js??clonedRuleSet-43.use[1]!../../../node_modules/.pnpm/postcss-loader@8.2.1_postcs_b46393c011c37beb4445b3ff96309729/node_modules/postcss-loader/dist/cjs.js!../../../node_modules/.pnpm/sass-loader@16.0.7_sass@1.99.0_webpack@5.106.2/node_modules/sass-loader/dist/cjs.js!./tailwind.scss\";\n      \n      \n\nvar options = {};\n\noptions.styleTagTransform = styleTagTransformFn;\noptions.setAttributes = setAttributes;\noptions.insert = insertFn.bind(null, \"head\");\noptions.domAPI = domAPI;\noptions.insertStyleElement = insertStyleElement;\n\nvar update = API(content, options);\n\n\n\nexport * from \"!!../../../node_modules/.pnpm/css-loader@7.1.4_webpack@5.106.2/node_modules/css-loader/dist/cjs.js??clonedRuleSet-43.use[1]!../../../node_modules/.pnpm/postcss-loader@8.2.1_postcs_b46393c011c37beb4445b3ff96309729/node_modules/postcss-loader/dist/cjs.js!../../../node_modules/.pnpm/sass-loader@16.0.7_sass@1.99.0_webpack@5.106.2/node_modules/sass-loader/dist/cjs.js!./tailwind.scss\";\n       export default content && content.locals ? content.locals : undefined;\n","import { createPinia } from 'pinia';\nimport { createApp } from 'vue';\nimport { teleportStyle } from '../util/script';\nimport { StatusBarManager } from './services/statusbar_manager';\nimport GlobalStatusBar from './views/GlobalStatusBar.vue';\nimport ReturnButton from './views/ReturnButton.vue';\nimport StartupNavigator from './views/StartupNavigator.vue';\n\n// 导入重构抽离的模块\nimport {\n  RETURN_BTN_CONTAINER_CLASS,\n  startChatMonitor,\n  STARTUP_CONTAINER_CLASS,\n  stopChatMonitor\n} from './hooks/useChatMonitor';\nimport { acquireInstanceLock, releaseInstanceLock } from './hooks/useInstanceLock';\nimport { setupTavernControls } from './hooks/useTavernControls';\n\n// 导入全局样式\nimport './styles/tailwind.scss';\n\nconst GLOBAL_STATUSBAR_CONTAINER_CLASS = 'ark-global-statusbar-mount-point';\n\n// --- 创建全局唯一的 Pinia 引擎 ---\n// 保证在不同挂载点 (开局UI、返回按钮、状态栏) 的 Vue 实例之间共享同一份内存数据\nconst globalPinia = createPinia();\n\nlet startupApp: ReturnType<typeof createApp> | null = null;\nlet returnBtnApp: ReturnType<typeof createApp> | null = null;\nlet globalStatusBarApp: ReturnType<typeof createApp> | null = null;\n\nlet destroyStyle: (() => void) | null = null;\n\n// --- 事件监听器引用，用于卸载时解绑 ---\nlet onMountStartup: ((e: Event) => void) | null = null;\nlet onMountReturn: ((e: Event) => void) | null = null;\nlet onUnmountAll: ((e: Event) => void) | null = null;\n\nfunction setupMountListeners() {\n  onMountStartup = (e: Event) => {\n    const customEvent = e as CustomEvent;\n    const containerEl = customEvent.detail.containerEl as HTMLElement;\n    \n    // 确保返回按钮已被清理\n    const existingReturnBtn = containerEl.querySelector(`.${RETURN_BTN_CONTAINER_CLASS}`);\n    if (existingReturnBtn) {\n      if (returnBtnApp) {\n        returnBtnApp.unmount();\n        returnBtnApp = null;\n      }\n      existingReturnBtn.remove();\n    }\n\n    // 检查是否已经挂载了开局 UI\n    if (containerEl.querySelector(`.${STARTUP_CONTAINER_CLASS}`) === null) {\n      console.info('[ARK_STATUSBAR] Mounting Startup Navigator...');\n      // 挂载前清空当前楼层现有的纯文本内容\n      containerEl.innerHTML = '';\n\n      const mountPoint = document.createElement('div');\n      mountPoint.className = STARTUP_CONTAINER_CLASS;\n      containerEl.appendChild(mountPoint);\n      \n      startupApp = createApp(StartupNavigator);\n      startupApp.use(globalPinia);\n      startupApp.mount(mountPoint);\n    }\n  };\n\n  onMountReturn = (e: Event) => {\n    const customEvent = e as CustomEvent;\n    const containerEl = customEvent.detail.containerEl as HTMLElement;\n\n    // 确保开局 UI 已被清理\n    const existingStartup = containerEl.querySelector(`.${STARTUP_CONTAINER_CLASS}`);\n    if (existingStartup) {\n      if (startupApp) {\n        startupApp.unmount();\n        startupApp = null;\n      }\n      existingStartup.remove();\n    }\n\n    // 检查是否已经挂载了返回按钮\n    if (containerEl.querySelector(`.${RETURN_BTN_CONTAINER_CLASS}`) === null) {\n      console.info('[ARK_STATUSBAR] Mounting Return Button...');\n      // 返回按钮追加到现有剧情内容后\n      const mountPoint = document.createElement('div');\n      mountPoint.className = RETURN_BTN_CONTAINER_CLASS;\n      containerEl.appendChild(mountPoint);\n      \n      returnBtnApp = createApp(ReturnButton);\n      returnBtnApp.use(globalPinia);\n      returnBtnApp.mount(mountPoint);\n    }\n  };\n\n  onUnmountAll = (e: Event) => {\n    const customEvent = e as CustomEvent;\n    const containerEl = customEvent.detail.containerEl as HTMLElement;\n\n    const existingStartup = containerEl.querySelector(`.${STARTUP_CONTAINER_CLASS}`);\n    if (existingStartup) {\n      if (startupApp) {\n        startupApp.unmount();\n        startupApp = null;\n      }\n      existingStartup.remove();\n    }\n\n    const existingReturnBtn = containerEl.querySelector(`.${RETURN_BTN_CONTAINER_CLASS}`);\n    if (existingReturnBtn) {\n      if (returnBtnApp) {\n        returnBtnApp.unmount();\n        returnBtnApp = null;\n      }\n      existingReturnBtn.remove();\n    }\n  };\n\n  document.addEventListener('ark:chat-mount-startup', onMountStartup);\n  document.addEventListener('ark:chat-mount-return', onMountReturn);\n  document.addEventListener('ark:chat-unmount-all', onUnmountAll);\n}\n\nfunction removeMountListeners() {\n  if (onMountStartup) document.removeEventListener('ark:chat-mount-startup', onMountStartup);\n  if (onMountReturn) document.removeEventListener('ark:chat-mount-return', onMountReturn);\n  if (onUnmountAll) document.removeEventListener('ark:chat-unmount-all', onUnmountAll);\n}\n\nfunction mountGlobalStatusBar() {\n  const ST_DOC = window.parent?.document || document;\n  let globalContainer = ST_DOC.querySelector(`.${GLOBAL_STATUSBAR_CONTAINER_CLASS}`);\n  if (!globalContainer) {\n    globalContainer = ST_DOC.createElement('div');\n    globalContainer.className = GLOBAL_STATUSBAR_CONTAINER_CLASS;\n    ST_DOC.body.appendChild(globalContainer);\n  } else {\n    if (globalStatusBarApp) {\n      globalStatusBarApp.unmount();\n      globalStatusBarApp = null;\n    }\n    globalContainer.innerHTML = '';\n  }\n\n  globalStatusBarApp = createApp(GlobalStatusBar);\n  globalStatusBarApp.use(globalPinia);\n  globalStatusBarApp.mount(globalContainer);\n}\n\n// -----------------------------------------------------------------------------\n// 引导程序 (Bootstrapper)\n// -----------------------------------------------------------------------------\nasync function bootstrap() {\n  if (!acquireInstanceLock()) return;\n\n  console.info('[ARK_STATUSBAR] Module Loaded. Bootstrapping...');\n\n  // --- 1. 初始化业务管理器 ---\n  const manager = StatusBarManager.getInstance();\n  await manager.init();\n\n  // --- 2. 注册 Vue 挂载监听器 ---\n  setupMountListeners();\n\n  // --- 3. 注入外部控制台按钮 ---\n  setupTavernControls();\n\n  // --- 4. 准备渲染 UI ---\n  const { destroy } = teleportStyle();\n  destroyStyle = destroy;\n\n  // --- 5. 挂载全局状态栏 UI ---\n  mountGlobalStatusBar();\n\n  // --- 6. 启动轮询观测器 ---\n  startChatMonitor();\n\n  console.info('[ARK_STATUSBAR] Bootstrapping Complete.');\n}\n\n$(() => {\n  bootstrap();\n});\n\n// -----------------------------------------------------------------------------\n// 卸载阶段清理 (Teardown)\n// -----------------------------------------------------------------------------\n$(window).on('pagehide', () => {\n  // 1. 停止观测器\n  stopChatMonitor();\n\n  // 2. 移除 DOM 挂载监听器\n  removeMountListeners();\n\n  // 3. 清理业务管理器\n  StatusBarManager.getInstance().destroy();\n\n  // 4. 清理样式\n  if (destroyStyle) {\n    destroyStyle();\n    destroyStyle = null;\n  }\n\n  // 5. 卸载 Vue 实例\n  if (globalStatusBarApp) {\n    globalStatusBarApp.unmount();\n    globalStatusBarApp = null;\n  }\n  if (startupApp) {\n    startupApp.unmount();\n    startupApp = null;\n  }\n  if (returnBtnApp) {\n    returnBtnApp.unmount();\n    returnBtnApp = null;\n  }\n\n  // 6. 物理清理挂载点\n  const ST_DOC = window.parent?.document || document;\n  ST_DOC.querySelectorAll(`.${STARTUP_CONTAINER_CLASS}`).forEach(el => el.remove());\n  ST_DOC.querySelectorAll(`.${RETURN_BTN_CONTAINER_CLASS}`).forEach(el => el.remove());\n  ST_DOC.querySelectorAll(`.${GLOBAL_STATUSBAR_CONTAINER_CLASS}`).forEach(el => el.remove());\n\n  // 7. 释放全局单例锁\n  releaseInstanceLock();\n});\n","export function setupTavernControls() {\r\n  const BTN_NAME = '📖 控制台开关';\r\n  if (\r\n    typeof appendInexistentScriptButtons === 'function' ||\r\n    typeof (window.parent as any).appendInexistentScriptButtons === 'function'\r\n  ) {\r\n    const appendFn =\r\n      typeof appendInexistentScriptButtons === 'function'\r\n        ? appendInexistentScriptButtons\r\n        : (window.parent as any).appendInexistentScriptButtons;\r\n    const getEventFn = typeof getButtonEvent === 'function' ? getButtonEvent : (window.parent as any).getButtonEvent;\r\n    const globalEventOn = typeof eventOn === 'function' ? eventOn : (window.parent as any).eventOn;\r\n\r\n    try {\r\n      appendFn([{ name: BTN_NAME, visible: true }]);\r\n      const btnEvent = getEventFn(BTN_NAME);\r\n      if (globalEventOn) {\r\n        globalEventOn(btnEvent, () => {\r\n          // 派发事件以切换全局 UI 的显示状态\r\n          document.dispatchEvent(new CustomEvent('ark:system-toggle'));\r\n        });\r\n      }\r\n    } catch (e) {\r\n      console.error('[ARK_STATUSBAR] Failed to inject button:', e);\r\n    }\r\n  }\r\n}\r\n","import iframe_srcdoc from './iframe_srcdoc.html';\n\nexport async function loadReadme(url: string): Promise<boolean> {\n  const readme = await fetch(url);\n  if (!readme.ok) {\n    return false;\n  }\n  const readme_text = await readme.text();\n  replaceScriptInfo(readme_text);\n  return true;\n}\n\nexport function teleportStyle(\n  append_to: JQuery.Selector | JQuery.htmlString | JQuery.TypeOrArray<Element | DocumentFragment> | JQuery = 'head',\n): { destroy: () => void } {\n  const $div = $(`<div>`)\n    .attr('script_id', getScriptId())\n    .append($(`head > style`, document).clone())\n    .appendTo(append_to);\n\n  return {\n    destroy: () => $div.remove(),\n  };\n}\n\nexport function createScriptIdIframe(): JQuery<HTMLIFrameElement> {\n  return $(`<iframe>`).attr({\n    script_id: getScriptId(),\n    frameborder: 0,\n    srcdoc: iframe_srcdoc,\n  }) as JQuery<HTMLIFrameElement>;\n}\n\nexport function createScriptIdDiv(): JQuery<HTMLDivElement> {\n  return $('<div>').attr('script_id', getScriptId()) as JQuery<HTMLDivElement>;\n}\n\nexport function reloadOnChatChange(): EventOnReturn {\n  let chat_id = SillyTavern.getCurrentChatId();\n  return eventOn(tavern_events.CHAT_CHANGED, new_chat_id => {\n    if (chat_id !== new_chat_id) {\n      chat_id = new_chat_id;\n      window.location.reload();\n    }\n  });\n}\n"],"names":["___CSS_LOADER_EXPORT___","push","module","id","exports","cssWithMappingToString","list","toString","this","map","item","content","needLayer","concat","length","join","i",